import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Übersetzungsstatus","description":"Status der deutschen UIX-Dokumentation gegenüber der englischen Originaldokumentation.","frontmatter":{"title":"Übersetzungsstatus","description":"Status der deutschen UIX-Dokumentation gegenüber der englischen Originaldokumentation."},"headers":[],"relativePath":"projects/uix/translation-status.md","filePath":"projects/uix/translation-status.md","lastUpdated":1793126212000}'),a={name:"projects/uix/translation-status.md"};function d(o,e,s,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ubersetzungsstatus" tabindex="-1">Übersetzungsstatus <a class="header-anchor" href="#ubersetzungsstatus" aria-label="Permalink to &quot;Übersetzungsstatus&quot;">​</a></h1><h2 id="inhaltsabgleich-vom-27-10-2026" tabindex="-1">Inhaltsabgleich vom 27.10.2026 <a class="header-anchor" href="#inhaltsabgleich-vom-27-10-2026" aria-label="Permalink to &quot;Inhaltsabgleich vom 27.10.2026&quot;">​</a></h2><p>Die verbliebenen Hinweise des vollständigen DE/EN/FR-Inventars sind <a href="/documentation-review.json">einzeln bewertet</a>. Die kanonische englische Vorschau bleibt erhalten. Zwei widersprüchliche Cache-Absätze wurden anhand der Implementierung berichtigt: <code>clear-cache</code> erhält <code>localStorage</code> und die Browser-Mod-Kennung. Die Prüfsummen der angepassten englischen Seiten sind mit dieser redaktionellen Korrektur fortgeschrieben; kanonische Quellen und Codebeispiele bleiben unverändert.</p><p>18 französische Referenzseiten enthalten zusammen 199 ergänzende Konfigurationen aus den deutschen Beispielen, mit französischen Überschriften und unveränderten technischen Werten. Fehlende Erläuterungen zu Themes, Foundries, DOM-Pfaden und Browser-Overrides wurden ergänzt; ein englischer Theme-Absatz ist jetzt französisch. Historische Versionsangaben und unterschiedlich gegliederte Zusammenfassungen sind als geprüfte Unterschiede erfasst. Stabile Basis und kanonische Vorschau werden weiterhin getrennt ausgewiesen. Dies ist eine Dokumentationsprüfung, kein neuer HA-Laufzeittest.</p><p>Diese Seite dokumentiert den aktuellen Abgleich der deutschen UIX-Dokumentation mit der englischen Originaldokumentation.</p><h2 id="inhaltsprufung-vom-26-10-2026" tabindex="-1">Inhaltsprüfung vom 26.10.2026 <a class="header-anchor" href="#inhaltsprufung-vom-26-10-2026" aria-label="Permalink to &quot;Inhaltsprüfung vom 26.10.2026&quot;">​</a></h2><p>Alle <strong>64 kanonischen Seiten</strong> wurden erneut gegen die englische Quelle <a href="https://github.com/Lint-Free-Technology/uix/tree/26e54e6d4973231a393933e6479ed1b03cc86cd3/docs/source" target="_blank" rel="noreferrer"><code>26e54e6</code></a> geprüft. <code>dev</code> ist seit dem letzten Abgleich unverändert; die Originalwebsite nennt weiterhin <strong>9.0.0-beta.2</strong>. Stabile Basis bleibt <strong>8.4.0</strong>.</p><ul><li><strong>Korrigiert:</strong> Die deutschen Abschnittshintergründe verwenden jetzt die dokumentierten Variablen für Farbe/Deckkraft und <code>background.uix</code> statt eines abweichenden Beispiels. Der seltene <code>custom:mod-card</code>-Ausweg, seine Warnung und der Template-Debug-Marker samt 20-Sekunden-Cachefrist sind ergänzt.</li><li><strong>DE/FR ergänzt:</strong> vollständige Badge-Beispiele und Broker-Direktiven für Badge, Lock und Action Handler. Französisch erhält den korrekten geerbten Standard der Tooltip-Pfeilgröße und den Theme-Debugging-Kontext.</li><li><strong>DE vertieft:</strong> YAML-Anker, Includes, Secrets, Merge-Ergebnisse und leere Billet-Slots in Foundries; außerdem Throttling, Section-/Footer-Molds, Background-Adapter, Map-Filter, Event-Zusammenführung und eingebettetes More-info. Lock-/Overlay-Positionen und der Overlay-Rahmenradius nennen die tatsächlichen Standardwerte.</li><li>Die <a href="/projects/uix/translation-review.json">Prüfübersicht</a> hält Quellen- und Übersetzungsstände pro Seite fest. Tabellen-Schlüssel, Gegenstücke und ergänzte Beispiele wurden geprüft; Build, Links, Medien und Sprachmetadaten werden separat mitgeprüft. Technische Schlüssel und übernommene Codebeispiele bleiben in Originalschreibweise.</li></ul><p>DE/FR bleiben redaktionelle Übersetzungen mit teils kompakterem Aufbau. Der Abgleich ist keine unabhängige Übersetzungszertifizierung und kein Home-Assistant-Laufzeittest. Die EN-Sprachwahl öffnet weiterhin die Originalseite in einem neuen Tab.</p><h2 id="gesamtprufung-vom-22-10-2026" tabindex="-1">Gesamtprüfung vom 22.10.2026 <a class="header-anchor" href="#gesamtprufung-vom-22-10-2026" aria-label="Permalink to &quot;Gesamtprüfung vom 22.10.2026&quot;">​</a></h2><p>Alle <strong>64 kanonischen Markdown-Seiten</strong> wurden gegen den eingefrorenen <a href="https://github.com/Lint-Free-Technology/uix/tree/26e54e6d4973231a393933e6479ed1b03cc86cd3/docs/source" target="_blank" rel="noreferrer">englischen Stand <code>26e54e6</code></a> geprüft. Gegenüber dem letzten Vorschau-Abgleich <code>e2e0701</code> sind Forge-Referenz, Foundries und Forge-Übersicht geändert; die übrigen 61 Originalseiten sind unverändert. Die stabile Veröffentlichung bleibt <strong>8.4.0</strong>, die geprüfte Vorschau ist <strong>9.0.0-beta.2</strong>.</p><ul><li><strong>EN:</strong> Alle 64 Seiten enthalten jetzt den englischen Originalinhalt statt Platzhaltern, mit angepassten Hinweiskästen, Abschnittsankern, Links, Medienpfaden und CC-BY-4.0-Quellenangabe. Original- und Ausgabedateien sind im <a href="/projects/uix/canonical-review.json">Prüfmanifest</a> durch Hashes zugeordnet; Codeblöcke werden mit normalisierter äußerer Einrückung, entfernten Leerzeichen am Zeilenende und vereinheitlichten Zeilenenden verglichen.</li><li><strong>DE/FR:</strong> Ergänzt sind Broker-Badge, Text content, Lock und Action handler; die Forge-Vorschau umfasst nun auch Typanker, native Basis in Foundries und Blank Badges. Französisch erhält fehlende Tooltip-Optionen, Scrollverhalten und aktuelle CSS-Standardwerte.</li><li><strong>DE:</strong> Foundry-Beispiele korrigiert (<code>uix_foundries</code>, oberstes <code>foundry</code>, <code>forge.billets</code>, native Typregel, Spark-Merge und Makro-<code>returns</code>). FAQ zur Card-mod-Kompatibilität bis 4.2.1 und zur Migration berichtigt; Browser-Event-Action, Cache-Erhalt, Integrationsabhängigkeit, State-Throttling, Billet-Priorität und fehlende Spark-CSS-Optionen ergänzt.</li><li>Alle kanonischen Seiten besitzen DE/EN/FR-Gegenstücke. Der alte englische Pfad <code>style-custom-panels</code> verweist auf <code>style-frame-panels</code>. Fehlende Originalmedien wurden ergänzt; Sprach-/Quellenverweise und lokale Bilder werden mitgeprüft.</li></ul><p>Das ist ein Quellen-, Inhalts- und Dokumentationsabgleich; die DE/FR-Texte bleiben redaktionell übersetzte Fassungen, keine zeilenidentischen Kopien und keine unabhängig zertifizierte Übersetzung. Es wurden keine HA-Systeme aufgerufen oder verändert. Release-Metadaten bleiben 8.4.0; Vorschauversion und -revision werden separat geführt. Der zuvor veröffentlichte gezielte Forge-Abgleich bleibt unten als Historie erhalten.</p><h2 id="forge-abgleich-vom-22-10-2026" tabindex="-1">Forge-Abgleich vom 22.10.2026 <a class="header-anchor" href="#forge-abgleich-vom-22-10-2026" aria-label="Permalink to &quot;Forge-Abgleich vom 22.10.2026&quot;">​</a></h2><p>Die <a href="https://github.com/Lint-Free-Technology/uix/commit/1badf70befb9c9d3d7b06c0eced75af7d552aff1" target="_blank" rel="noreferrer">kanonische Änderung <code>1badf70befb9</code></a> auf <code>dev</code> ergänzt den Verfügbarkeitshinweis für den visuellen Forge-Editor ab <strong>9.0.0-beta.2</strong>. Der dazugehörige Abschnitt fehlte bisher auf unseren Seiten. Eine mit der Quelle abgeglichene Zusammenfassung ist jetzt in <strong>DE/EN/FR</strong> verfügbar: Native, Forge, Element, Foundry und Export; außerdem <code>element_base</code>/<code>element</code>, Typanker, Null-/Deaktivierungssemantik und YAML-Grenzen.</p><p>Die englische Forge-Seite ist für diesen Abschnitt kein Platzhalter mehr. Die vollständige kanonische Referenz bleibt verlinkt. Dies ist keine vollständige Neuübersetzung aller UIX-Seiten oder aller <code>dev</code>-Änderungen. Stabile Basis, Release-Metadaten und Footer bleiben unverändert; der frühere umfassendere Vorschau-Abgleich bis 9.0.0-beta.0 ist vom neuen gezielten Forge-Abgleich getrennt. Reine Dokumentationsänderung ohne HA-Installation oder Laufzeittest.</p><h2 id="abgleich-vom-09-10-2026-stabile-basis-8-4-0-vorschau-9-0-0-beta-0" tabindex="-1">Abgleich vom 09.10.2026: stabile Basis 8.4.0, Vorschau 9.0.0-beta.0 <a class="header-anchor" href="#abgleich-vom-09-10-2026-stabile-basis-8-4-0-vorschau-9-0-0-beta-0" aria-label="Permalink to &quot;Abgleich vom 09.10.2026: stabile Basis 8.4.0, Vorschau 9.0.0-beta.0&quot;">​</a></h2><p>Die kanonischen Meldungen zu <code>2db023d236c9</code>, <code>c800e607f23d</code>, <code>9b5858f57678</code> und <code>22f8d93f0131</code> wurden in Deutsch und Französisch abgeglichen. Der geprüfte <code>dev</code>-Stand ist <a href="https://github.com/Lint-Free-Technology/uix/commit/e2e070193b3f77b251dcfe05104a4d791a8e9a03" target="_blank" rel="noreferrer"><code>e2e0701</code></a>, Version <strong>9.0.0-beta.0</strong>. Das Original nennt weiterhin <strong>8.4.0</strong> als stabile Version auf <code>master</code>; Release-Link, Footer und stabile Metadaten behalten diesen Stand.</p><ul><li>Veraltete Beta-Hinweise in Broker-Direktiven, Popover-Aktion, Form Spark, App-Panels und Theme-Schriften entfernt.</li><li>FAQ zur nicht unterdrückbaren Reload-Meldung und zum automatischen Neuladen nach 60 Sekunden ergänzt. Die neue Auslieferung der beim Home-Assistant-Start geladenen Version ist als Vorschau gekennzeichnet.</li><li>Forge-Referenz, Foundries und Übersicht um die geschichtete Konfiguration ergänzt: <code>element_base</code>, Forge-Overlay <code>element</code>, lokale <code>element_disabled_paths</code>, Merge-Regeln, native Sichtbarkeit und Template-Kontexte. Verfügbarkeit ausdrücklich ab <strong>9.0.0-beta.0</strong>, nicht 8.4.0 oder 8.4.1.</li><li>Die Originalanimation <code>forge-auto-entities.gif</code> aus <code>9b5858f57678</code> für DE/FR übernommen. Die stabile <code>source_revision</code> bleibt unverändert; Vorschauversion, Branch und Revision werden separat in den Metadaten erfasst.</li></ul><h2 id="stand-uix-8-4-0" tabindex="-1">Stand: UIX 8.4.0 <a class="header-anchor" href="#stand-uix-8-4-0" aria-label="Permalink to &quot;Stand: UIX 8.4.0&quot;">​</a></h2><ul><li>Abgleich am <strong>08.10.2026</strong> gegen den stabilen Release <a href="https://github.com/Lint-Free-Technology/uix/releases/tag/v8.4.0" target="_blank" rel="noreferrer"><code>v8.4.0</code></a> vom 07.10.2026, Revision <a href="https://github.com/Lint-Free-Technology/uix/commit/71b8ccd38202257c070ae9970a7aac12a68a6389" target="_blank" rel="noreferrer"><code>71b8ccd</code></a>.</li><li>Benötigt <strong>Home Assistant 2026.10.0 oder neuer</strong>.</li><li><code>git diff c70d1275f1fb08514291feb4c9181a748408b798 v8.4.0 -- docs/source docs/mkdocs.yml</code> zeigt keine Änderungen. Der zuletzt abgeglichene kanonische Dokumentationsstand ist damit auch der Stand des stabilen Releases.</li><li>Berücksichtigt sind Form Spark, Popover-Aktion, interne Frame-Laufzeit, <code>uix-fonts</code>, Entitätsbild-Overrides in Kartenübersichten und Broker-Ergebnisreferenzen. Die Frame-Option bleibt experimentell und standardmäßig aus.</li><li>Die bislang fehlende <a href="./forge/sparks/badge">Badge-Spark-Referenz</a> wurde ergänzt. Deutsch und Französisch haben nun Gegenstücke zu allen 64 kanonischen Markdown-Pfaden sowie eine eigene Statusseite. Die Badge-Seite ist eine kompakte Referenz mit vollständigen Options- und CSS-Tabellen; weitere Originalbeispiele sind verlinkt.</li><li>Übersicht, Footer, Release-Link, JSON-Metadaten und <code>llms.txt</code> nennen 8.4.0. Versionshinweise auf einzelnen Seiten kennzeichnen die Einführung der Funktionen; frühere Prüfberichte unten sind historische Stände.</li><li>In Französisch wurden 17 englische Kompatibilitäts-Anchors ergänzt und damit 36 bestehende Abschnittslinks repariert; französische Titel und Abschnittsadressen bleiben erhalten.</li><li>Die Prüfung umfasst Quellenvergleich, Seitenabdeckung, Build, Links, Sprachverweise und kopierbare Beispiele. Sie ersetzt keine erneute Satz-für-Satz-Prüfung aller Altübersetzungen und keine Home-Assistant-Laufzeittests.</li></ul><h2 id="historischer-stand-uix-8-3-1" tabindex="-1">Historischer Stand: UIX 8.3.1 <a class="header-anchor" href="#historischer-stand-uix-8-3-1" aria-label="Permalink to &quot;Historischer Stand: UIX 8.3.1&quot;">​</a></h2><ul><li>Alle 61 Markdown-Seiten des abgeglichenen englischen Stands haben deutsche Gegenstücke.</li><li>Geprüft gegen den stabilen UIX-Release <code>8.3.1</code> vom 22.09.2026, Revision <a href="https://github.com/Lint-Free-Technology/uix/commit/add5557c0ee13a98c9fe249bed06d215606f2507" target="_blank" rel="noreferrer"><code>add5557</code></a>.</li><li>Die Release-Korrekturen sind berücksichtigt: Die Map-Spark-Seite nennt den Fix für Home Assistant 2026.9.0; außerdem dokumentiert diese Statusseite den Kompatibilitätsfix für das Laden von Web Awesome auf älteren Geräten, einschließlich iOS 15.</li><li>Die zuvor abgeglichenen Ergänzungen aus UIX <code>8.3.0-beta.8</code> sind nun Bestandteil der stabilen 8.3-Reihe; Hinweise auf Beta-Versionen bleiben dort erhalten, wo sie die Einführung einzelner Funktionen beschreiben.</li><li>Frühere <code>8.2.0-beta</code>-Hinweise wurden mit dem stabilen Release <code>8.2.0</code> zusammengeführt.</li><li>Die Seiten <a href="./using/icons">Icons</a> und <a href="./using/images">Bilder</a> wurden gezielt näher an die englische Originaldokumentation angeglichen, da diese Bereiche bei der externen Prüfung aufgefallen sind.</li><li>Die Seite <a href="./forge/sparks/button">Button Spark</a> enthält die mit UIX <code>8.2.0</code> veröffentlichte <code>outlined</code>-Darstellung.</li><li>Lizenz- und Footer-Hinweise nennen die CC-BY-4.0-Lizenz der originalen UIX-Dokumentation.</li><li>Die deutsche Fassung wird weiter mit dem englischen Original abgeglichen, sobald neue UIX-Änderungen im Original-Repository verfügbar sind.</li></ul><h2 id="broker-abgleich-vom-05-10-2026" tabindex="-1">Broker-Abgleich vom 05.10.2026 <a class="header-anchor" href="#broker-abgleich-vom-05-10-2026" aria-label="Permalink to &quot;Broker-Abgleich vom 05.10.2026&quot;">​</a></h2><p>Die Seiten <a href="./broker/directives#direktiven-regeln">Directives</a> und <a href="./broker/rules#kompakte-captured-data-form">Rules</a> wurden gezielt mit den kanonischen Änderungen <a href="https://github.com/Lint-Free-Technology/uix/commit/105b8cd446ea082553be627530efe8a752d57dec" target="_blank" rel="noreferrer"><code>105b8cd</code></a> und <a href="https://github.com/Lint-Free-Technology/uix/commit/04d8e14b006f24e795997c68191f9fde3652bd22" target="_blank" rel="noreferrer"><code>04d8e14</code></a> abgeglichen. Ergänzt sind Ergebnisreferenzen <code>@&lt;directive-id&gt;</code>, das unveränderte YAML-Beispiel und der Hinweis auf UIX <code>8.4.0-beta.9</code>. Diese Referenzen sind nur in Direktiven-Regeln verfügbar. Die entsprechenden französischen Seiten wurden ebenfalls aktualisiert; die stabile Basis bleibt UIX <code>8.3.1</code>.</p><h2 id="aktualisierung-vom-24-09-2026" tabindex="-1">Aktualisierung vom 24.09.2026 <a class="header-anchor" href="#aktualisierung-vom-24-09-2026" aria-label="Permalink to &quot;Aktualisierung vom 24.09.2026&quot;">​</a></h2><p>Der Dokumentationsstand wurde gegen den stabilen UIX-Release <code>8.3.1</code> geprüft. Das Release nennt zwei Fehlerbehebungen: Die Map-Spark-Funktion wurde nach Änderungen an Home Assistant 2026.9.0 wiederhergestellt, und ein Ladeproblem von Web Awesome auf älteren Geräten (darunter iOS 15) wird umgangen. Diese Punkte sind Release-Änderungen; sie führen keine neue Konfigurationsoption ein.</p><h2 id="abgleich-vom-30-09-2026" tabindex="-1">Abgleich vom 30.09.2026 <a class="header-anchor" href="#abgleich-vom-30-09-2026" aria-label="Permalink to &quot;Abgleich vom 30.09.2026&quot;">​</a></h2><p>Die deutschen Seiten zu <a href="./using/entities">Entitäten</a> und <a href="./using/images">Bildern</a> wurden mit der kanonischen Dokumentationsrevision <a href="https://github.com/Lint-Free-Technology/uix/commit/7d7c95acb449c1222d8a338e3d9423f91ff0f2a2" target="_blank" rel="noreferrer"><code>7d7c95a</code></a> abgeglichen. Ergänzt wurden die CSS-Parts für Map-Marker ab Home Assistant 2026.10.0 sowie <code>hui-map-overview</code> und der Hinweis auf Entity-spezifische Bildüberschreibungen. Die stabile Basis bleibt UIX <code>8.3.1</code>; der Footer weist zusätzlich auf die abgeglichenen Dokumentationsänderungen bis UIX <code>8.4.0-beta.3</code> hin.</p><h2 id="aktualisierung-vom-13-09-2026" tabindex="-1">Aktualisierung vom 13.09.2026 <a class="header-anchor" href="#aktualisierung-vom-13-09-2026" aria-label="Permalink to &quot;Aktualisierung vom 13.09.2026&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Abgeglichene Inhalte</th></tr></thead><tbody><tr><td>Broker-Direktiven</td><td><code>tooltip</code>, <code>for: previous</code>, <code>trigger</code>, <code>open</code>, Inline-Styles, Regeln und Anchors; bestehender <code>directive</code>-Templatekontext</td></tr><tr><td>Tooltip Spark</td><td>HA-Standardwerte, Textfarben-Fallback, manuelle Aktivierung, Hover über dem Inhalt, begrenzte Höhe und Scrollen, korrigiertes Styling-Beispiel</td></tr><tr><td>Regeln</td><td><code>user</code>, <code>user_is_admin</code>, <code>hash</code>, <code>search</code>, <code>panel</code>, Property-Pfade und Grenzen von <code>block</code></td></tr><tr><td>Actions</td><td><code>locked_action</code>, Sperreinträge, Code-Dialog, Fehlversuche und Hinweis auf die Grenze des Frontend-Schutzes</td></tr><tr><td>DOM und Beispiele</td><td>Broker-Konsolenhelfer, Property-Existenz, vollständiges Sidebar-YAML einschließlich Button und Filter für Entity-Trigger</td></tr><tr><td>Bilder und Navigation</td><td>Entity-Badge mit <code>show_entity_picture</code>, Broker als dritter Bereich und Verweise auf experimentelle Extras</td></tr><tr><td>Veröffentlichung</td><td>Englische/deutsche Sprachverweise im HTML, Metadatenvertrag und Vorabversions-Kompatibilität beschrieben</td></tr><tr><td>Kopierbare Beispiele</td><td>Maskierte Jinja-Klammern auf 17 Seiten durch echte Template-Begrenzer ersetzt, einschließlich eines zusätzlich gefundenen verschachtelten Codeblocks; Inline-Code und defekte Abschnittslinks korrigiert</td></tr></tbody></table><h2 id="abgleich-vom-24-09-2026" tabindex="-1">Abgleich vom 24.09.2026 <a class="header-anchor" href="#abgleich-vom-24-09-2026" aria-label="Permalink to &quot;Abgleich vom 24.09.2026&quot;">​</a></h2><p>Die UIX-Änderungen bis zur englischen Revision <a href="https://github.com/Lint-Free-Technology/uix/commit/8c6fb830d75477b30f035323161bac8d41599a78" target="_blank" rel="noreferrer"><code>8c6fb83</code></a> wurden für Deutsch und Französisch geprüft. Dabei wurden die Änderungen aus <a href="https://github.com/Lint-Free-Technology/uix/commit/a43f3e2bf03edb808c0ea8d83af426d06626181e" target="_blank" rel="noreferrer"><code>a43f3e2</code></a> und <a href="https://github.com/Lint-Free-Technology/uix/commit/8711f1eb4a2a479a2a43d748c0b26f94b040e87a" target="_blank" rel="noreferrer"><code>8711f1e</code></a> mitberücksichtigt.</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Abgeglichene Inhalte</th></tr></thead><tbody><tr><td>Extras</td><td>Die frühere Seite zum Styling von Custom Panels im iframe wurde durch <a href="./extras/style-frame-panels">Frame-Panels stylen</a> ersetzt. Sie beschreibt die experimentelle, interne Laufzeit, die Aktivierung, unterstützte gleichursprüngliche Frames und die Framework-Kompatibilität.</td></tr><tr><td>UIX Styling</td><td><a href="./using/custom-panels">Custom Panels</a> unterscheidet nun zwischen direkt geladenen Panels, Panel-Frames und App-Frames. <a href="./using/apps">App- und Ingress-Panels</a> dokumentiert die Theme-Schlüssel, Slug-Auflösung und den Geltungsbereich von <code>uix-app</code>.</td></tr><tr><td>Navigation und Medien</td><td>Deutsche Seitenleiste und Übersichtsseiten verweisen auf die neuen Seiten; das App-Panel-Beispielbild wurde auf den kanonischen Stand aktualisiert.</td></tr></tbody></table><p>Die App-Frame-Funktion ist laut Original ab UIX <code>3.4.0-beta.1</code> verfügbar. Die experimentelle Option für Frame-Panels ist standardmäßig deaktiviert. Die stabile Metadatenbasis der deutschen Übersetzung bleibt davon unberührt.</p><p>Die stabile Versionsangabe in <code>uix-docs.json</code> ist auf <code>8.3.1</code> / <code>add5557</code> aktualisiert.</p><p>Die Dokumentation wird mit VitePress gebaut. Die ergänzende Prüfung <code>python scripts/check-uix-docs.py</code> kontrolliert nach dem Build die gerenderten Codebeispiele, UIX-Linkziele und Sprachverweise. Home-Assistant-Laufzeittests sämtlicher Beispiele sind damit nicht abgedeckt.</p><h2 id="redaktionelle-prufung" tabindex="-1">Redaktionelle Prüfung <a class="header-anchor" href="#redaktionelle-prufung" aria-label="Permalink to &quot;Redaktionelle Prüfung&quot;">​</a></h2><p>Die Änderungen aus den genannten Benachrichtigungen sind abgeglichen. Eine unabhängige Satz-für-Satz-Prüfung sämtlicher bestehender Langseiten bleibt davon getrennt; besonders umfangreich sind folgende Seiten:</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Seiten</th></tr></thead><tbody><tr><td>Konzepte</td><td><code>concepts/application</code>, <code>concepts/dom</code></td></tr><tr><td>Styling</td><td><code>using/entities</code>, <code>using/templates</code>, <code>using/themes</code>, <code>using/view-backgrounds</code></td></tr><tr><td>Forge</td><td><code>forge/forge</code>, <code>forge/foundries</code></td></tr><tr><td>Sparks</td><td><code>background</code>, <code>button</code>, <code>event</code>, <code>grid</code>, <code>lock</code>, <code>map</code>, <code>more-info</code>, <code>overlay-icon</code>, <code>search</code>, <code>state-badge</code>, <code>tile-icon</code>, <code>tooltip</code></td></tr><tr><td>Extras</td><td><code>uix-actions</code>, <code>frontend-states-throttling</code>, <code>dialog-styling-delay</code></td></tr></tbody></table><h2 id="maßgebliche-quelle" tabindex="-1">Maßgebliche Quelle <a class="header-anchor" href="#maßgebliche-quelle" aria-label="Permalink to &quot;Maßgebliche Quelle&quot;">​</a></h2><p>Die englische Originaldokumentation bleibt die maßgebliche Quelle:</p><p><a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">https://uix.lf.technology/</a></p><h2 id="abgleich-vom-08-10-2026" tabindex="-1">Abgleich vom 08.10.2026 <a class="header-anchor" href="#abgleich-vom-08-10-2026" aria-label="Permalink to &quot;Abgleich vom 08.10.2026&quot;">​</a></h2><p>Die Änderungen der englischen Dokumentation in Revision <a href="https://github.com/Lint-Free-Technology/uix/commit/c70d1275f1fb08514291feb4c9181a748408b798" target="_blank" rel="noreferrer"><code>c70d1275f1fb</code></a>, Branch <code>master</code>, wurden mit Deutsch und Französisch abgeglichen.</p><ul><li>Neuer <a href="./forge/sparks/form">Form Spark</a> mit Schema, Markdown, Submit/Clear, Dichte, CSS-Variablen und Formularwerten in Aktionen.</li><li>Neue <a href="./extras/uix-actions#popover">Popover-Aktion</a>, einschließlich Karten, Header-Icons, Footer-Buttons, Formularintegration und Originalbeispielen.</li><li>Broker: synchrones <code>block</code>, Regel-Anchors, wiederverwendeter Panel-Zustand, Tooltip-Referenz <code>previous</code>, JavaScript-Promises und Styling-Lebenszyklus-Events korrigiert. Veraltete geplante Funktionen entfernt.</li><li>Navigation, Forge-Übersichten und FAQ ergänzt; sechs neue oder geänderte Originalmedien übernommen.</li><li>Die bereits vorhandenen Änderungen an Frame-/App-Panels wurden erneut verglichen. Ergänzt wurden die Änderungen an Entitätsbildern, Kartenmarkern und Theme-Schriften.</li></ul><p>Dieser Abgleich betrifft die gemeldeten Dokumentationsänderungen. Die stabile Metadatenbasis bleibt <code>8.3.1</code>; er ersetzt keine vollständige Prüfung sämtlicher Seiten gegen eine spätere stabile Veröffentlichung. YAML-/JavaScript-Beispiele und Medien des neuen Form-Sparks und der Popover-Aktion stammen unverändert aus der englischen Quelle. Der Doku-Build und die Linkprüfung überprüfen die Veröffentlichung; sie führen keine Home-Assistant-Laufzeittests aus.</p>',47)])])}const b=n(a,[["render",d]]);export{g as __pageData,b as default};
